package com.ryanjei.orushio.pve.map;
import com.ryanjei.orushio.pve.domain.MapProfileId;import com.ryanjei.orushio.pve.persistence.*;import java.nio.file.*;import java.time.Instant;import java.util.*;import java.util.stream.Collectors;
public final class YamlMapProfileRepository implements MapProfileRepository{
 private final Path root;public YamlMapProfileRepository(Path root){this.root=root.toAbsolutePath().normalize();}
 public List<MapProfile> findAll(){if(!Files.isDirectory(root))return List.of();try(var s=Files.list(root)){return s.filter(Files::isDirectory).map(p->load(p.resolve("profile.yml"))).flatMap(Optional::stream).sorted(Comparator.comparing(p->p.mapId().value())).toList();}catch(Exception e){throw new RepositoryException("マップ一覧を読み込めません。",e);}}
 public Optional<MapProfile> find(MapProfileId id){return load(path(id).resolve("profile.yml"));}
 public void save(MapProfile p){Map<String,String>v=new LinkedHashMap<>();v.put("schemaVersion","1");v.put("mapId",p.mapId().value());v.put("displayName",p.displayName());v.put("enabled",Boolean.toString(p.enabled()));v.put("templateDirectory",p.templateDirectory());v.put("createdAt",p.createdAt().toString());p.points().forEach((k,l)->{if(!MapProfile.RETIRED_POINT_FIELDS.contains(k))v.put("points."+k,encodePoints(l));});p.areas().forEach((k,l)->{if(!MapProfile.RETIRED_AREA_FIELDS.contains(k))v.put("areas."+k,encodeAreas(l));});v.put("spawnMarkers",encodeMarkers(p.spawnMarkers()));v.put("setupMarkers",encodeSetupMarkers(p.setupMarkers()));new AtomicYamlStore(path(p.mapId()).resolve("profile.yml")).write(v);}
 public void delete(MapProfileId id){try{Files.deleteIfExists(path(id).resolve("profile.yml"));}catch(Exception e){throw new RepositoryException("MapProfileを削除できません。",e);}}
 private Optional<MapProfile> load(Path f){return new AtomicYamlStore(f).read().map(v->{if(!"1".equals(v.get("schemaVersion")))throw new RepositoryException("未対応のMapProfile schemaVersionです。");Map<String,List<BlockPoint>>p=new LinkedHashMap<>();Map<String,List<Cuboid>>a=new LinkedHashMap<>();v.forEach((k,x)->{if(k.startsWith("points."))p.put(k.substring(7),decodePoints(x));if(k.startsWith("areas."))a.put(k.substring(6),decodeAreas(x));});List<SetupMarker>setup=new ArrayList<>(decodeSetupMarkers(v.getOrDefault("setupMarkers","")));migratePoints(p,setup);migrateGates(a,setup);boolean requestedEnabled=strictBoolean(v.get("enabled"));MapProfile candidate=new MapProfile(new MapProfileId(v.get("mapId")),v.get("displayName"),false,v.get("templateDirectory"),p,a,Instant.parse(v.get("createdAt")),decodeMarkers(v.getOrDefault("spawnMarkers","")),setup);return requestedEnabled&&candidate.setupComplete()?candidate.withEnabled(true):candidate;});}
 private Path path(MapProfileId id){Path p=root.resolve(id.value()).normalize();if(!p.getParent().equals(root))throw new RepositoryException("mapIdの保存先が不正です。");return p;}
 private static String point(BlockPoint p){return p.x()+","+p.y()+","+p.z()+","+p.yaw()+","+p.pitch();}private static BlockPoint point(String v){String[]p=v.split(",");if(p.length!=5)throw new RepositoryException("地点データが不正です。");return new BlockPoint(Integer.parseInt(p[0]),Integer.parseInt(p[1]),Integer.parseInt(p[2]),Float.parseFloat(p[3]),Float.parseFloat(p[4]));}
 private static String encodePoints(List<BlockPoint>l){return l.stream().map(YamlMapProfileRepository::point).collect(Collectors.joining(";"));}private static List<BlockPoint>decodePoints(String s){return s.isBlank()?List.of():Arrays.stream(s.split(";")).map(YamlMapProfileRepository::point).toList();}
 private static String encodeAreas(List<Cuboid>l){return l.stream().map(a->a.minX()+","+a.minY()+","+a.minZ()+","+a.maxX()+","+a.maxY()+","+a.maxZ()).collect(Collectors.joining(";"));}private static List<Cuboid>decodeAreas(String s){if(s.isBlank())return List.of();return Arrays.stream(s.split(";")).map(v->{String[]a=v.split(",");if(a.length!=6)throw new RepositoryException("範囲データが不正です。");return new Cuboid(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]),Integer.parseInt(a[3]),Integer.parseInt(a[4]),Integer.parseInt(a[5]));}).toList();}
 private static String encodeMarkers(List<SpawnMarker>l){return l.stream().map(m->m.markerId()+","+m.areaId()+","+point(m.position())+","+m.enabled()).collect(Collectors.joining(";"));}private static List<SpawnMarker>decodeMarkers(String s){if(s.isBlank())return List.of();return Arrays.stream(s.split(";")).map(v->{String[]p=v.split(",");if(p.length!=8)throw new RepositoryException("Spawn Markerデータが不正です。");return new SpawnMarker(UUID.fromString(p[0]),p[1],new BlockPoint(Integer.parseInt(p[2]),Integer.parseInt(p[3]),Integer.parseInt(p[4]),Float.parseFloat(p[5]),Float.parseFloat(p[6])),strictBoolean(p[7]));}).toList();}
 private static String encodeSetupMarkers(List<SetupMarker>l){return l.stream().map(m->m.markerId()+","+m.markerType()+","+point(m.position())+","+m.enabled()).collect(Collectors.joining(";"));}private static List<SetupMarker>decodeSetupMarkers(String s){if(s.isBlank())return List.of();return Arrays.stream(s.split(";")).map(v->{String[]p=v.split(",");if(p.length!=8)throw new RepositoryException("設定Markerデータが不正です。");return new SetupMarker(UUID.fromString(p[0]),SetupMarkerType.valueOf(p[1]),new BlockPoint(Integer.parseInt(p[2]),Integer.parseInt(p[3]),Integer.parseInt(p[4]),Float.parseFloat(p[5]),Float.parseFloat(p[6])),strictBoolean(p[7]));}).toList();}
 private static void migratePoints(Map<String,List<BlockPoint>>points,List<SetupMarker>markers){migrate(points,"farmSpawn",SetupMarkerType.FARM_RESPAWN,markers);migrate(points,"combatEntry",SetupMarkerType.GAME_START,markers);migrate(points,"normalCoreCandidates",SetupMarkerType.NORMAL_CORE,markers);migrate(points,"finalCore",SetupMarkerType.FINAL_CORE,markers);migrate(points,"finalEntryTrigger",SetupMarkerType.FINAL_AREA_ENTRY,markers);}
 private static void migrate(Map<String,List<BlockPoint>>points,String key,SetupMarkerType type,List<SetupMarker>markers){for(BlockPoint point:points.getOrDefault(key,List.of()))if(markers.stream().noneMatch(marker->marker.markerType()==type&&sameBlock(marker.position(),point)))markers.add(new SetupMarker(stableLegacyId(type,point),type,point,true));}
 private static void migrateGates(Map<String,List<Cuboid>>areas,List<SetupMarker>markers){for(Cuboid gate:areas.getOrDefault("gateRegions",List.of())){long count=((long)gate.maxX()-gate.minX()+1L)*((long)gate.maxY()-gate.minY()+1L)*((long)gate.maxZ()-gate.minZ()+1L);if(count>100_000L)continue;for(int x=gate.minX();x<=gate.maxX();x++)for(int y=gate.minY();y<=gate.maxY();y++)for(int z=gate.minZ();z<=gate.maxZ();z++){BlockPoint point=new BlockPoint(x,y,z,0,0);if(markers.stream().noneMatch(marker->marker.markerType()==SetupMarkerType.FINAL_GATE&&sameBlock(marker.position(),point)))markers.add(new SetupMarker(stableLegacyId(SetupMarkerType.FINAL_GATE,point),SetupMarkerType.FINAL_GATE,point,true));}}}
 private static UUID stableLegacyId(SetupMarkerType type,BlockPoint point){return UUID.nameUUIDFromBytes(("legacy-setup-marker|"+type+"|"+point.x()+","+point.y()+","+point.z()).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private static boolean sameBlock(BlockPoint a,BlockPoint b){return a.x()==b.x()&&a.y()==b.y()&&a.z()==b.z();}
 private static boolean strictBoolean(String v){if(!"true".equals(v)&&!"false".equals(v))throw new RepositoryException("真偽値が不正です。");return Boolean.parseBoolean(v);}
}
